     1→// FreeLang v4 — AST 노드 정의
     2→
     3→// ============================================================
     4→// 타입 표기 (Type Annotations)
     5→// ============================================================
     6→
     7→export type TypeAnnotation =
     8→  | { kind: "i32" }
     9→  | { kind: "i64" }
    10→  | { kind: "f64" }
    11→  | { kind: "bool" }
    12→  | { kind: "string" }
    13→  | { kind: "void" }
    14→  | { kind: "array"; element: TypeAnnotation }
    15→  | { kind: "channel"; element: TypeAnnotation }
    16→  | { kind: "option"; element: TypeAnnotation }
    17→  | { kind: "result"; ok: TypeAnnotation; err: TypeAnnotation }
    18→  | { kind: "struct_ref"; name: string }
    19→  | { kind: "fn"; params: TypeAnnotation[]; returnType: TypeAnnotation }
    20→  | { kind: "type_param"; name: string }                                  // Generic 타입 파라미터 (T, K, V)
    21→  | { kind: "generic_ref"; name: string; typeArgs: TypeAnnotation[] };   // 제네릭 타입 참조 (List<T>, Map<K,V>)
    22→
    23→// ============================================================
    24→// 패턴 (Match Patterns) — SPEC_05 Q8: 7종
    25→// ============================================================
    26→
    27→export type Pattern =
    28→  | { kind: "ident"; name: string }         // x → 바인딩
    29→  | { kind: "literal"; value: Expr }         // 42, "hello", true
    30→  | { kind: "ok"; inner: Pattern }           // Ok(v)
    31→  | { kind: "err"; inner: Pattern }          // Err(e)
    32→  | { kind: "some"; inner: Pattern }         // Some(v)
    33→  | { kind: "none" }                         // None
    34→  | { kind: "wildcard" };                    // _
    35→
    36→export type MatchArm = {
    37→  pattern: Pattern;
    38→  body: Expr;
    39→};
    40→
    41→// ============================================================
    42→// 식 (Expressions) — 값을 만든다
    43→// ============================================================
    44→
    45→export type FnParam = {
    46→  name: string;
    47→  type?: TypeAnnotation;
    48→};
    49→
    50→export type Expr =
    51→  | { kind: "int_lit"; value: number; line: number; col: number }
    52→  | { kind: "float_lit"; value: number; line: number; col: number }
    53→  | { kind: "string_lit"; value: string; line: number; col: number }
    54→  | { kind: "bool_lit"; value: boolean; line: number; col: number }
    55→  | { kind: "ident"; name: string; line: number; col: number }
    56→  | { kind: "binary"; op: string; left: Expr; right: Expr; line: number; col: number }
    57→  | { kind: "unary"; op: string; operand: Expr; line: number; col: number }
    58→  | { kind: "call"; callee: Expr; args: Expr[]; line: number; col: number }
    59→  | { kind: "index"; object: Expr; index: Expr; line: number; col: number }
    60→  | { kind: "field_access"; object: Expr; field: string; line: number; col: number }
    61→  | { kind: "assign"; target: Expr; value: Expr; line: number; col: number }
    62→  | { kind: "try"; operand: Expr; line: number; col: number }
    63→  | { kind: "if_expr"; condition: Expr; then: Expr[]; else_: Expr[]; line: number; col: number }
    64→  | { kind: "match_expr"; subject: Expr; arms: MatchArm[]; line: number; col: number }
    65→  | { kind: "array_lit"; elements: Expr[]; line: number; col: number }
    66→  | { kind: "struct_lit"; structName: string; fields: { name: string; value: Expr }[]; line: number; col: number }
    67→  | { kind: "fn_lit"; params: FnParam[]; returnType?: TypeAnnotation; body: Expr; line: number; col: number }
    68→  | { kind: "block_expr"; stmts: Stmt[]; expr: Expr | null; line: number; col: number };
    69→
    70→// ============================================================
    71→// 문 (Statements) — 값을 만들지 않는다
    72→// ============================================================
    73→
    74→export type Param = {
    75→  name: string;
    76→  type: TypeAnnotation;
    77→};
    78→
    79→export type StructField = {
    80→  name: string;
    81→  type: TypeAnnotation;
    82→};
    83→
    84→export type Stmt =
    85→  | { kind: "var_decl"; name: string; mutable: boolean; type: TypeAnnotation | null; init: Expr; line: number; col: number }
    86→  | { kind: "fn_decl"; name: string; typeParams: string[]; params: Param[]; returnType: TypeAnnotation; body: Stmt[]; line: number; col: number }
    87→  | { kind: "struct_decl"; name: string; typeParams: string[]; fields: StructField[]; line: number; col: number }
    88→  | { kind: "if_stmt"; condition: Expr; then: Stmt[]; else_: Stmt[] | null; line: number; col: number }
    89→  | { kind: "match_stmt"; subject: Expr; arms: MatchArm[]; line: number; col: number }
    90→  | { kind: "for_stmt"; variable: string; iterable: Expr; body: Stmt[]; line: number; col: number }
    91→  | { kind: "for_of_stmt"; variable: string; iterable: Expr; body: Stmt[]; line: number; col: number }
    92→  | { kind: "while_stmt"; condition: Expr; body: Stmt[]; line: number; col: number }
    93→  | { kind: "break_stmt"; line: number; col: number }
    94→  | { kind: "continue_stmt"; line: number; col: number }
    95→  | { kind: "spawn_stmt"; body: Stmt[]; line: number; col: number }
    96→  | { kind: "return_stmt"; value: Expr | null; line: number; col: number }
    97→  | { kind: "expr_stmt"; expr: Expr; line: number; col: number };
    98→
    99→// ============================================================
