     1→// FreeLang v6: Virtual Machine
     2→
     3→import { Op, Value, Chunk } from "./compiler";
     4→import { getBuiltins } from "./stdlib/builtins";
     5→import { JumpTable, OffsetCalculator } from "./jump-table";
     6→import { MemoryAllocator } from "./memory-allocator";
     7→
     8→type BuiltinFn = (args: Value[], vm: VM) => Value;
     9→type Frame = { retAddr: number; baseSlot: number; fn: string; upvalues: Value[] };
    10→type TryHandler = { catchAddr: number; stackDepth: number; frameDepth: number };
    11→type LoopContext = {
    12→  addr: number;
    13→  iterationCount: number;
    14→  // Phase 3.8: State snapshot for memory isolation
    15→  stackHeightAtEntry: number;
    16→  globalSnapshotAtEntry: Map<string, Value>;
    17→  localSnapshotAtEntry: Value[];
    18→  stateChanges: { varName: string; before: Value; after: Value }[];
    19→};
    20→
    21→export class VM {
    22→  private stack: Value[] = [];
    23→  private globals = new Map<string, Value>();
    24→  private frames: Frame[] = [];
    25→  private tryStack: TryHandler[] = [];
    26→  private ip = 0;
    27→  private output: string[] = [];
    28→  private builtinFns: Record<string, BuiltinFn>;
    29→  // Phase 8: try/catch error handling
    30→  private lastError: Value | null = null;
    31→  private inTryCall = false;
    32→  // Phase 3.7: Safety guard & iteration tracking
    33→  // Phase 3.9: Jump Table & Offset Optimization
    34→  private jumpTable: JumpTable;
    35→  private offsetCalc: OffsetCalculator = new OffsetCalculator();
    36→  // Phase 5.9: Dynamic Memory Allocator
    37→  private memoryAllocator: MemoryAllocator = new MemoryAllocator();
    38→
