    10→registerBuiltin("error_new", ([msgArg, typeArg]) => {
    11→  const message = msgArg?.tag === "str" ? msgArg.val : String(msgArg);
    12→  const type = typeArg?.tag === "str" ? typeArg.val : "Error";
    13→
    14→  const errorObj = new Map<string, Value>();
    15→  errorObj.set("message", { tag: "str", val: message });
    16→  errorObj.set("type", { tag: "str", val: type });
    17→  errorObj.set("__error", { tag: "bool", val: true });
    18→
    19→  return { tag: "object", val: errorObj };
    20→});
    21→
    22→/**
    23→ * error_message(err: object) → str
