    26→registerBuiltin("error_message", ([err]) => {
    27→  if (err?.tag === "object") {
    28→    const message = err.val.get("message");
    29→    if (message?.tag === "str") {
    30→      return message;
    31→    }
    32→  }
    33→  return { tag: "str", val: "Unknown error" };
    34→});
    35→
    36→/**
    37→ * error_type(err: object) → str
